('glowna', 'Strona Główna', '<section class="wyszukiwarka"><label for="search-input">Szukaj produktu:</label><input type="text" id="search-input" placeholder="Wpisz nazwę..."><p id="search-status" role="status">Znaleziono produktów: 3</p></section><div class="katalog"><article class="karta"><h3><a href="index.php?idp=produkt">Myszka SteelSeries Rival 650 Wireless</a></h3><img src="img/p-steelseries-rival-650-62456.png" alt="Myszka bezprzewodowa SteelSeries Rival 650"><p>Nowoczesna myszka bezprzewodowa dla graczy z systemem ciężarków.</p><p><strong>549,99 zł</strong></p></article><article class="karta"><h3><a href="index.php?idp=produkt">Arctis Nova 7 Wireless Gen 2</a></h3><img src="img/artis.png" alt="Słuchawki bezprzewodowe Arctis Nova 7"><p>Zestaw słuchawkowy do gier z obsługą łączności bezprzewodowej.</p><p><strong>649,99 zł</strong></p></article><article class="karta"><h3><a href="index.php?idp=produkt">Apex Pro TKL Gen 3 White US</a></h3><img src="img/apex.png" alt="Klawiatura mechaniczna Apex Pro TKL"><p>Bezprzewodowa klawiatura magnetyczna z regulacją punktu aktywacji.</p><p><strong>1059,99 zł</strong></p></article></div><section id="lab3-demo" class="lab3-sekcja"><h2>Laboratorium 3 - Animacje jQuery i AJAX</h2><div class="anim-kontener"><button type="button" id="anim-a" class="anim-box" aria-pressed="false">Obiekt A (Kliknij)</button><button type="button" id="anim-b" class="anim-box">Obiekt B (Najedź / Fokus)</button><button type="button" id="anim-c" class="anim-box">Obiekt C (Kliknij 5x)</button></div><div class="lab3-panel"><p id="status-c" role="status">Kroki obiektu C: 0 / 5</p><button type="button" id="reset-ac">Resetuj A i C</button></div><hr><div class="lab3-ajax"><button type="button" id="check-server">Sprawdź serwer</button><p id="server-status" role="status">Status serwera: nie sprawdzono</p></div></section>', 1),
('produkt', 'Produkt', '<article class="karta"><h2>Myszka SteelSeries Rival 650 Wireless</h2><img src="img/p-steelseries-rival-650-62456.png" alt="Myszka SteelSeries Rival 650" style="max-width: 350px; height: auto;"><p>Cena: <strong>549,99 zł</strong></p><p>Myszka dla graczy z systemem szybkiego ładowania oraz podwójnym sensorem.</p><p><a href="index.php?idp=glowna">Wróć do strony głównej</a> lub przejdź do <a href="lab4.php">Katalogu PHP</a>.</p></article>', 1),
('kontakt', 'Kontakt', '<form action="index.php?idp=kontakt" method="get" id="contact-form"><label for="e-mail">email: (pole obowiązkowe)</label><input required type="email" name="email" id="e-mail"><label for="product-select">produkt: (pole obowiązkowe)</label><select required name="produkt" id="product-select"><option value="">Wybierz produkt</option><option value="p1">Myszka SteelSeries rival 650 Wireless</option><option value="p2">Arctis Nova 7 Wireless Gen 2</option><option value="p3">Apex Pro TKL Gen 3 White - US</option></select><label for="quantity-input">ilosc-sztuk: (1-5) (pole obowiązkowe)</label><input required type="number" name="ilosc" min="1" max="5" step="1" id="quantity-input"><p id="live-calculation">Wybierz produkt i ilość (1-5), aby zobaczyć wycenę.</p><label for="message-input">wiadomość: (10-500 znaków) (pole obowiązkowe)</label><textarea required name="wiadomosc" minlength="10" maxlength="500" id="message-input"></textarea><span id="message-error" style="color: #ff4444; font-weight: bold;"></span><button type="submit">Sprawdź zapytanie</button></form><section id="summary-section" style="margin-top: 15px; white-space: pre-line; font-weight: bold;"></section>', 1),
('filmy', 'Filmy', '<section class="filmy-sekcja"><h2>Filmy i recenzje sprzętu komputerowego</h2><p>Zapraszamy do obejrzenia materiałów wideo prezentujących akcesoria dla graczy.</p><div class="filmy-lista"><article class="karta film-karta"><h3>1. Prezentacja myszki bezprzewodowej SteelSeries</h3><iframe class="film-ramka" src="https://www.youtube.com/embed/IM0hLJta-p0" title="Prezentacja wideo myszki komputerowej" allowfullscreen></iframe><p>Odnośnik do materiału: <a href="https://www.youtube.com/watch?v=IM0hLJta-p0" target="_blank" rel="noopener noreferrer">Otwórz film 1 bezpośrednio w serwisie wideo</a></p></article><article class="karta film-karta"><h3>2. Test zestawu słuchawkowego dla graczy Arctis</h3><iframe class="film-ramka" src="https://www.youtube.com/embed/L7rRXDiJVK8" title="Materiał testowy wideo dla słuchawek" allowfullscreen></iframe><p>Odnośnik do materiału: <a href="https://www.youtube.com/watch?v=L7rRXDiJVK8" target="_blank" rel="noopener noreferrer">Otwórz film 2 bezpośrednio w serwisie wideo</a></p></article><article class="karta film-karta"><h3>3. Klawiatury mechaniczne i ergonomia stanowiska</h3><iframe class="film-ramka" src="https://www.youtube.com/embed/XSJjjDxWjWU" title="Prezentacja działania klawiatury mechanicznej" allowfullscreen></iframe><p>Odnośnik do materiału: <a href="https://www.youtube.com/watch?v=XSJjjDxWjWU" target="_blank" rel="noopener noreferrer">Otwórz film 3 bezpośrednio w serwisie wideo</a></p></article></div></section>', 1),
